//
// Benchmark harness. NOT installed.
//
// Every number this program reports measures a COMPLETED operation: the
// operation is finished, including its durable commit, before the clock is
// stopped. Nothing here measures enqueue, submission, or accept latency, and no
// before/after performance claim is made or implied by these numbers.
//
// Inputs are SYNTHETIC: the assets, obligations, and facility identifiers are
// generated by this program and correspond to no real facility. The durability
// cost that is included in each measurement is REAL and incurred on the host.

#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <string>
#include <vector>

#include "decommissioning_fabric/engine.hpp"
#include "decommissioning_fabric/time.hpp"

namespace df = decommissioning_fabric;

namespace {

struct Sample {
  std::int64_t nanos{0};
  std::uint64_t durable_bytes{0};
};

[[nodiscard]] double Percentile(const std::vector<std::int64_t>& sorted, double fraction) {
  if (sorted.empty()) {
    return 0.0;
  }
  const double index = fraction * static_cast<double>(sorted.size() - 1U);
  const std::size_t low = static_cast<std::size_t>(index);
  const std::size_t high = (std::min)(low + 1U, sorted.size() - 1U);
  const double weight = index - static_cast<double>(low);
  return static_cast<double>(sorted[low]) * (1.0 - weight) +
         static_cast<double>(sorted[high]) * weight;
}

void Report(const char* name, const char* input_class, const std::vector<Sample>& samples,
            std::uint64_t completed) {
  std::vector<std::int64_t> times;
  times.reserve(samples.size());
  std::uint64_t durable_bytes = 0;
  for (const Sample& sample : samples) {
    times.push_back(sample.nanos);
    durable_bytes += sample.durable_bytes;
  }
  std::sort(times.begin(), times.end());

  std::printf("%-26s input=%-10s completed=%llu\n", name, input_class,
              static_cast<unsigned long long>(completed));
  if (times.empty()) {
    std::printf("  (no completed operations)\n");
    return;
  }
  std::printf("  p50=%8.1f us  p95=%8.1f us  p99=%8.1f us  max=%8.1f us\n",
              Percentile(times, 0.50) / 1000.0, Percentile(times, 0.95) / 1000.0,
              Percentile(times, 0.99) / 1000.0,
              static_cast<double>(times.back()) / 1000.0);
  std::printf("  durable_bytes_total=%llu  durable_bytes_per_completed_op=%.1f\n",
              static_cast<unsigned long long>(durable_bytes),
              completed == 0U ? 0.0
                              : static_cast<double>(durable_bytes) /
                                    static_cast<double>(completed));
  std::fflush(stdout);
}

}  // namespace

int main(int argc, char** argv) {
  std::uint64_t iterations = 2000;
  std::string store = "bench-store";
  for (int index = 1; index < argc; ++index) {
    const std::string argument(argv[index]);
    if (argument == "--iterations" && index + 1 < argc) {
      iterations = std::strtoull(argv[++index], nullptr, 10);
    } else if (argument == "--store" && index + 1 < argc) {
      store = argv[++index];
    } else {
      std::fprintf(stderr, "usage: dfab_bench [--iterations N] [--store DIR]\n");
      return 2;
    }
  }
  if (iterations == 0U) {
    iterations = 1U;
  }

  // Benchmarks 1 to 3 hold the store open; benchmark 4 measures recovery, which
  // requires the store to be released first. The scope below is what releases it,
  // and the closure is why the lock is not held across the recovery measurement.
  {
    df::Engine::Options options;
    options.store_directory = store;
    options.store.create_if_missing = true;
    auto opened = df::Engine::Open(std::move(options));
    if (!opened.ok()) {
      std::fprintf(stderr, "dfab_bench: %s\n", opened.error().to_string().c_str());
      return 1;
    }
    df::Engine& engine = opened.value();

  // ---- 1. Completed durable commits through a validation-heavy mutation -----
  {
    std::vector<Sample> samples;
    samples.reserve(static_cast<std::size_t>(iterations));
    std::uint64_t completed = 0;
    for (std::uint64_t index = 0; index < iterations; ++index) {
      df::GenerationAdvanceRequest advance;
      advance.kind = df::GenerationKind::facility_epoch;
      advance.expected_current = engine.generations().facility_epoch.value();
      advance.incarnation = df::CurrentIncarnation();
      advance.at = df::Timestamp{df::ManualClock::kDefaultStartNanos +
                                 static_cast<std::int64_t>(index)};
      advance.reason = "benchmark";
      const std::int64_t started = df::MonotonicCounter::NowNanos();
      auto result = engine.AdvanceGeneration(advance);
      const std::int64_t elapsed = df::MonotonicCounter::NowNanos() - started;
      if (!result.ok()) {
        std::fprintf(stderr, "dfab_bench: %s\n", result.error().to_string().c_str());
        return 1;
      }
      ++completed;
      samples.push_back(Sample{elapsed, engine.last_commit().record_bytes});
    }
    Report("generation_advance", "SYNTHETIC", samples, completed);
  }

  // ---- 2. Completed plan creations, each including its own durable commit ---
  {
    std::vector<Sample> samples;
    samples.reserve(static_cast<std::size_t>(iterations));
    std::uint64_t completed = 0;
    for (std::uint64_t index = 0; index < iterations; ++index) {
      const std::uint64_t asset_id = 0x100000ULL + index;
      df::RegisterAssetRequest registration;
      registration.id = df::AssetId::FromValue(asset_id);
      registration.site = df::SiteId::FromValue(0x2001U);
      registration.rack = df::RackId::FromValue(0x3001U);
      registration.hardware_generation = df::HardwareGeneration::FromValue(1);
      registration.firmware_generation = df::FirmwareGeneration::FromValue(1);
      registration.active_authority = df::AuthorityMask{df::kAllAuthorityBits};
      registration.incarnation = df::CurrentIncarnation();
      registration.at = df::Timestamp{df::ManualClock::kDefaultStartNanos};
      if (!engine.RegisterAsset(registration).ok()) {
        break;
      }

      df::Request request;
      request.kind = df::RequestKind::create_plan;
      request.attempt = df::AttemptId::FromValue(index + 1U);
      request.incarnation = df::CurrentIncarnation();
      request.at = df::Timestamp{df::ManualClock::kDefaultStartNanos +
                                 static_cast<std::int64_t>(index)};
      df::CreatePlanPayload payload;
      payload.asset = df::AssetId::FromValue(asset_id);
      payload.rationale = "benchmark";
      request.payload = std::move(payload);

      const std::int64_t started = df::MonotonicCounter::NowNanos();
      auto result = engine.Submit(request);
      const std::int64_t elapsed = df::MonotonicCounter::NowNanos() - started;
      if (!result.ok()) {
        std::fprintf(stderr, "dfab_bench: %s\n", result.error().to_string().c_str());
        return 1;
      }
      ++completed;
      samples.push_back(Sample{elapsed, engine.last_commit().record_bytes});
    }
    Report("plan_create", "SYNTHETIC", samples, completed);
  }

  // ---- 3. Refusals: measured separately BECAUSE they have no durable cost ---
  {
    std::vector<Sample> samples;
    samples.reserve(static_cast<std::size_t>(iterations));
    std::uint64_t completed = 0;
    for (std::uint64_t index = 0; index < iterations; ++index) {
      df::Request request;
      request.kind = df::RequestKind::conclude_draining;
      request.attempt = df::AttemptId::FromValue(0x900000ULL + index);
      request.incarnation = df::CurrentIncarnation();
      request.at = df::Timestamp{df::ManualClock::kDefaultStartNanos};
      request.fence.asset = df::AssetId::FromValue(0x1ULL);
      request.fence.revision = df::Revision::FromValue(1);
      request.payload = df::ConcludeDrainingPayload{};
      const std::int64_t started = df::MonotonicCounter::NowNanos();
      auto result = engine.Submit(request);
      const std::int64_t elapsed = df::MonotonicCounter::NowNanos() - started;
      if (result.ok()) {
        std::fprintf(stderr, "dfab_bench: expected the refusal benchmark to be refused\n");
        return 1;
      }
      ++completed;
      samples.push_back(Sample{elapsed, 0});
    }
    Report("refused_request", "SYNTHETIC", samples, completed);
    std::printf("  (no durable bytes: a refused request is not an effect)\n");
  }
  }  // release the store before measuring recovery

  // ---- 4. Recovery: open and close, each a completed recovery ---------------

  {
    std::vector<Sample> samples;
    samples.reserve(static_cast<std::size_t>(iterations));
    std::uint64_t completed = 0;
    for (std::uint64_t index = 0; index < iterations; ++index) {
      const std::int64_t started = df::MonotonicCounter::NowNanos();
      df::Engine::Options reopen_options;
      reopen_options.store_directory = store;
      auto reopened = df::Engine::Open(std::move(reopen_options));
      const std::int64_t elapsed = df::MonotonicCounter::NowNanos() - started;
      if (!reopened.ok()) {
        std::fprintf(stderr, "dfab_bench: %s\n", reopened.error().to_string().c_str());
        return 1;
      }
      ++completed;
      samples.push_back(Sample{elapsed, 0});
    }
    Report("store_recovery", "REAL", samples, completed);
  }

  std::printf("\nMethodology: each sample covers one COMPLETED operation including its durable\n"
              "commit; enqueue and submit latency are never measured. Facility, asset, and\n"
              "obligation inputs are SYNTHETIC. Durability, locking, and filesystem behaviour\n"
              "are REAL and incurred on this host. Counts are reported so no value here is a\n"
              "before/after comparison.\n");
  return 0;
}
